import 'dart:convert';
import 'dart:async';
import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:musify/services/spotify_csv_importer.dart';
import 'package:musify/services/spotify_zip_importer.dart';

void main() {
  final fixtures = <String, String>{
    'csv':
        'UEsDBBQAAAAIAOQATl1mdiMFLAAAADMAAAAJAAAAc29uZ3MuY3N2CylKTM5W8EvMTdVxLCrJLC4BszWKNbncMouKS3T8y/NSi7iCU5Pz81KgHABQSwECFAAUAAAACADkAE5dZnYjBSwAAAAzAAAACQAAAAAAAAAAAAAAgAEAAAAAc29uZ3MuY3N2UEsFBgAAAAABAAEANwAAAFMAAAAAAA==',
    'stored':
        'UEsDBBQAAAAAAOQATl2bt5EZGQAAABkAAAAJAAAAc29uZ3MudHN2VGl0bGUJQXJ0aXN0CkZpcnN0CU93bmVyClBLAQIUABQAAAAAAOQATl2bt5EZGQAAABkAAAAJAAAAAAAAAAAAAACAAQAAAABzb25ncy50c3ZQSwUGAAAAAAEAAQA3AAAAQAAAAAAA',
    'json':
        'UEsDBBQAAAAIAIYBTl2+xEO+RAAAAFUAAAAQAAAAWW91ckxpYnJhcnkuSlNPTqtWKilKTM4uVrJSiK6GsJWsFJTcMouKS5R0FJQSi0oyi0tAQv7lealFSrWxIMGcpNJcqBYwGyTvmZ6XX5SaolQbWwsAUEsBAhQAFAAAAAgAhgFOXb7EQ75EAAAAVQAAABAAAAAAAAAAAAAAAIABAAAAAFlvdXJMaWJyYXJ5LkpTT05QSwUGAAAAAAEAAQA+AAAAcgAAAAAA',
    'membership':
        'UEsDBBQAAAAIAOQATl2LXu/eMQAAAC8AAAAJAAAAc29uZ3MuY3N2C8ksyUnVcSwqySwu0QnISazMySwuUfBLzE3lcsssKi7R8S/PSy3SCSjKLEssSeUCAFBLAQIUABQAAAAIAOQATl2LXu/eMQAAAC8AAAAJAAAAAAAAAAAAAACAAQAAAABzb25ncy5jc3ZQSwUGAAAAAAEAAQA3AAAAWAAAAAAA',
    'path':
        'UEsDBBQAAAAIAOQATl20IWK1GwAAABkAAAAMAAAALi4vc29uZ3MuY3N2C8ksyUnVcSwqySwu4XLLLCou0fEvz0st4gIAUEsBAhQAFAAAAAgA5ABOXbQhYrUbAAAAGQAAAAwAAAAAAAAAAAAAAIABAAAAAC4uL3NvbmdzLmNzdlBLBQYAAAAAAQABADoAAABFAAAAAAA=',
    'nested':
        'UEsDBBQAAAAIAOQATl20IWK1GwAAABkAAAAQAAAAZm9sZGVyL3NvbmdzLmNzdgvJLMlJ1XEsKsksLuFyyywqLtHxL89LLeICAFBLAQIUABQAAAAIAOQATl20IWK1GwAAABkAAAAQAAAAAAAAAAAAAACAAQAAAABmb2xkZXIvc29uZ3MuY3N2UEsFBgAAAAABAAEAPgAAAEkAAAAAAA==',
    'badjson':
        'UEsDBBQAAAAIAOQATl2CBAZoDQAAAAsAAAAQAAAAWW91ckxpYnJhcnkuanNvbqtWKilKTM4uVrKKBgBQSwECFAAUAAAACADkAE5dggQGaA0AAAALAAAAEAAAAAAAAAAAAAAAgAEAAAAAWW91ckxpYnJhcnkuanNvblBLBQYAAAAAAQABAD4AAAA7AAAAAAA=',
    'unknown':
        'UEsDBBQAAAAIAOQATl20IWK1GwAAABkAAAAJAAAAb3RoZXIudHh0C8ksyUnVcSwqySwu4XLLLCou0fEvz0st4gIAUEsBAhQAFAAAAAgA5ABOXbQhYrUbAAAAGQAAAAkAAAAAAAAAAAAAAIABAAAAAG90aGVyLnR4dFBLBQYAAAAAAQABADcAAABCAAAAAAA=',
  };
  Uint8List fixture(String key) => base64Decode(fixtures[key]!);
  Future<SpotifyImportPreview> parse(Uint8List bytes) =>
      SpotifyZipImporter.parseBytes(bytes, fileName: 'owned.ZIP');
  final rejected = throwsA(isA<SpotifyImportException>());
  int central(Uint8List b) =>
      ByteData.sublistView(b).getUint32(b.length - 6, Endian.little);
  test(
    'deflated CSV preserves row order and outer filename with visible entry',
    () async {
      final p = await parse(fixture('csv'));
      expect(p.fileName, 'owned.ZIP');
      expect(p.tracks.map((t) => t.title), ['First', 'Second']);
      expect(p.tracks.map((t) => t.sourceRow), [2, 3]);
      expect(p.notices.single, contains('songs.csv'));
    },
  );
  test('stored TSV uses tabs and existing parser', () async {
    expect((await parse(fixture('stored'))).tracks.single.title, 'First');
  });
  test('saved-track JSON retains its non-track disclosure', () async {
    final p = await parse(fixture('json'));
    expect(p.tracks.single.title, 'First');
    expect(p.notices.length, greaterThan(1));
  });
  for (final key in ['membership', 'path', 'nested', 'badjson', 'unknown']) {
    test('rejects $key without returning a partial preview', () async {
      await expectLater(parse(fixture(key)), rejected);
    });
  }
  for (final length in [0, 10, 21]) {
    test('rejects short archive $length', () async {
      await expectLater(parse(Uint8List(length)), rejected);
    });
  }
  test('rejects oversized input before decoding', () async {
    await expectLater(
      parse(Uint8List(SpotifyZipImporter.maxBytes + 1)),
      rejected,
    );
  });
  test('rejects archive comments and trailing records', () async {
    await expectLater(
      parse(Uint8List.fromList([...fixture('csv'), 0])),
      rejected,
    );
  });
  for (final mutation in [
    'count',
    'encryption',
    'descriptor',
    'method',
    'crc',
    'size',
    'centralName',
    'localName',
    'offset',
    'disk',
    'extra',
    'symlink',
  ]) {
    test('rejects inconsistent or unsupported $mutation', () async {
      final b = fixture('csv');
      final d = ByteData.sublistView(b);
      final c = central(b);
      final e = b.length - 22;
      switch (mutation) {
        case 'count':
          d.setUint16(e + 10, 2, Endian.little);
          break;
        case 'encryption':
          d.setUint16(c + 8, 1, Endian.little);
          break;
        case 'descriptor':
          d.setUint16(c + 8, 8, Endian.little);
          break;
        case 'method':
          d.setUint16(c + 10, 99, Endian.little);
          break;
        case 'crc':
          d.setUint32(c + 16, 0, Endian.little);
          d.setUint32(14, 0, Endian.little);
          break;
        case 'size':
          d.setUint32(c + 24, 1, Endian.little);
          d.setUint32(22, 1, Endian.little);
          break;
        case 'centralName':
          b[c + 46] = 120;
          break;
        case 'localName':
          b[30] = 120;
          break;
        case 'offset':
          d.setUint32(c + 42, 1, Endian.little);
          break;
        case 'disk':
          d.setUint16(e + 4, 1, Endian.little);
          break;
        case 'extra':
          d.setUint16(28, 1, Endian.little);
          break;
        case 'symlink':
          d.setUint32(c + 38, 0xa0000000, Endian.little);
          break;
      }
      await expectLater(parse(b), rejected);
    });
  }
  test('actual cancellation stops async inflation', () async {
    final cancel = Completer<void>();
    final result = SpotifyZipImporter.parseBytes(
      fixture('csv'),
      fileName: 'owned.zip',
      cancelled: cancel.future,
    );
    cancel.complete();
    await expectLater(result, rejected);
  });
  test('input archive stays byte-exact', () async {
    final b = fixture('csv');
    final before = Uint8List.fromList(b);
    await parse(b);
    expect(b, before);
  });
  test('forged small output size cannot admit a decompression bomb', () async {
    await expectLater(
      parse(
        base64Decode(
          '',
        ),
      ),
      rejected,
    );
  });
  test('all truncated byte prefixes reject as import errors', () async {
    final b = fixture('csv');
    for (var i = 0; i < b.length; i++) {
      await expectLater(parse(Uint8List.sublistView(b, 0, i)), rejected);
    }
  });
  test('valid JSON exactly at decoded 8 MiB limit is accepted', () async {
    expect(
      (await parse(
        base64Decode(
          '',
        ),
      )).tracks.single.title,
      'First',
    );
  });
  test('actual multi-file archive rejects instead of choosing', () async {
    await expectLater(
      parse(
        base64Decode(
          '',
        ),
      ),
      rejected,
    );
  });
  test('CSV beyond 10,000 rows rejects before save', () async {
    await expectLater(
      parse(
        base64Decode(
          '',
        ),
      ),
      rejected,
    );
  });
  test('already cancelled stored input never returns a preview', () async {
    final cancel = Completer<void>()..complete();
    await expectLater(
      SpotifyZipImporter.parseBytes(
        fixture('stored'),
        fileName: 'owned.zip',
        cancelled: cancel.future,
      ),
      rejected,
    );
  });
  test('event-loop cancellation is delivered during owned decoding', () async {
    final cancel = Completer<void>();
    Timer.run(cancel.complete);
    await expectLater(
      SpotifyZipImporter.parseBytes(
        fixture('csv'),
        fileName: 'owned.zip',
        cancelled: cancel.future,
      ),
      rejected,
    );
  });
  test(
    'ZIP strict flat CSV policy rejects unrecognized playlist-prefixed columns',
    () {
      expect(
        () => SpotifyCsvImporter.parseBytes(
          Uint8List.fromList(
            utf8.encode('Title,Artist,PlaylistURL\nFirst,Owner,Private\n'),
          ),
          fileName: 'songs.csv',
          rejectPlaylistMembership: true,
        ),
        rejected,
      );
    },
  );
  test('ZIP64 required version rejects even without size sentinels', () async {
    final b = fixture('csv');
    ByteData.sublistView(b).setUint16(central(b) + 6, 45, Endian.little);
    await expectLater(parse(b), rejected);
  });
}
